    float  opacity, alphaInfo;
    float2 dielectric;
    float4 volume;
    float4 specular;
    float4 specularMap;
    float4 sheen;
    float4 sheenMap;
    float4 film;
    float2 filmMap;
    float4 anisotropy;
    float2 clearcoat;
    float3 coatNormal;
