    float4 sheen = 0, sheenMap = 1;
    float2 filmMap = 1, anisotropy = 0;
    float2 clearcoat  = 0;
    InstanceData materialRecord = (InstanceData)0;
    float2 uv         = input.uv;
    float2 aoUV       = uv;
    float2 baseUV     = uv;
    float4 baseFactor = baseColorFactor, matFactor = materialFactor, emissionFactor = emissiveFactor;
